import gurobipy as gp
from gurobipy import GRB
products = []
benefit = {}
weight = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'products.csv':
        pname = rec['values']['ProductName']
        try:
            b = int(rec['values']['Value'])
            w = int(rec['values']['Weight'])
        except Exception:
            raise ValueError(f'Non-integer Value or Weight for product {pname}')
        products.append(pname)
        benefit[pname] = b
        weight[pname] = w
capacity = None
for rec in LEGACY_RECORDS:
    if rec['source'] == 'capacity.csv':
        try:
            capacity = int(rec['values']['Capacity'])
        except Exception:
            raise ValueError('Non-integer Capacity in capacity.csv')
        break
if capacity is None:
    raise ValueError('No capacity found in LEGACY_RECORDS')
for pname in products:
    if pname not in benefit or pname not in weight:
        raise ValueError(f'Missing benefit or weight for product {pname}')
m = gp.Model('Vehicle_Inventory')
x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((benefit[i] * x[i] for i in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[i] * x[i] for i in products)) <= capacity, name='cap')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')